package wgmodern;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.renderer.entity.player.PlayerRenderer;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.ItemStack;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.client.event.*;import com.mojang.math.Axis;
